            "اختيار الفلتر بيبدأ من معرفة جودة المياه عندك. أول خطوة إنك تقيس نسبة الأملاح الذائبة (TDS) بجهاز بسيط أو تطلب تحليل مياه مجاني من فريقنا.\n## لو نسبة الأملاح عالية\nفلاتر الأوزموسيس العكسي (5 أو 7 مراحل) هي الأنسب، لأن الممبرين بيشيل معظم الأملاح والمعادن الثقيلة.\n## لو المشكلة رواسب وصدأ\nفلتر جامبو على المدخل الرئيسي بيحمي البيت كله، وممكن تضيف عليه فلتر شرب في المطبخ.\n## لو الضغط ضعيف\nاختار فلتر بموتور رفع ضغط علشان الإنتاج يفضل ثابت.\nلو محتار، كلمنا على واتساب وهنرشحلك الأنسب لبيتك."],
        ['إمتى لازم تغيّر شمعات الفلتر؟', 'when-to-change-cartridges', 'مواعيد تغيير كل مرحلة في الفلتر وعلامات بتقولك إن الشمعات محتاجة تتغير.', $img('cartridges-set.svg'),
            "الشمعات هي خط الدفاع الأول عن صحتك وعن الممبرين، وتأخير تغييرها بيقلل كفاءة الفلتر.\n## المراحل الأولى (1، 2، 3)\nكل 3 إلى 6 شهور حسب كمية الرواسب في المياه.\n## الممبرين\nكل 18 إلى 24 شهر، أو لما قراءة الـ TDS بعد الفلتر تبدأ تعلى.\n## المراحل النهائية\nتقريباً كل سنة.\n## علامات إن الشمعات محتاجة تتغير\nضعف نزول المياه، تغير الطعم أو الريحة، أو ارتفاع قراءة جهاز الأملاح."],
        ['الفرق بين فلاتر 5 مراحل و7 مراحل', '5-vs-7-stages', 'إيه اللي بتضيفه المرحلتين الزيادة؟ وإمتى يستاهل تدفع الفرق؟', $img('ro-5.svg'),
            "الفلترين بيعتمدوا على نفس القلب: الممبرين اللي بيشيل الأملاح.\n## فلتر 5 مراحل\nثلاث شمعات تنقية أولية + ممبرين + كربون نهائي لتحسين الطعم. اختيار اقتصادي ممتاز.\n## فلتر 7 مراحل\nبيضيف مرحلة معادن ومرحلة ألكالاين أو تعقيم، وده بيدي طعم أحلى ومياه متوازنة أكتر.\n## نختار إيه؟\nلو الميزانية تسمح، الـ 7 مراحل أفضل على المدى الطويل. ولو عايز توفر، الـ 5 مراحل بيأدي الغرض بكفاءة."],
        ['يعني إيه TDS؟ ونسبة الأملاح الطبيعية في مياه الشرب', 'what-is-tds', 'شرح بسيط لقراءة جهاز الأملاح وإيه الأرقام المناسبة لمياه الشرب.', $img('tds.svg'),
            "الـ TDS هو مجموع الأملاح والمعادن الذائبة في المياه، وبيتقاس بوحدة جزء في المليون (ppm).\n## الأرقام المناسبة\nمياه الشرب الممتازة غالباً بين 50 و150 جزء في المليون بعد الفلتر.\n## إزاي تقيس؟\nاغمس جهاز القياس في كوباية مياه من الحنفية، وبعدين من الفلتر، وقارن القراءتين.\n## القراءة عالية؟\nممكن يكون الممبرين محتاج يتغير، أو الفلتر محتاج صيانة. احجز زيارة وهنفحصه لك."],
    ];
    $st = $pdo->prepare('INSERT INTO posts (title, slug, excerpt, image, content, created_at) VALUES (?,?,?,?,?,?)');
    foreach ($posts as $k => $p) $st->execute([...$p, date('Y-m-d H:i:s', time() - ($k + 1) * 86400 * 3)]);

    // ---------- الصفحات الثابتة ----------
    $pages = [
        ['services', 'خدماتنا', "## تركيب الفلاتر\nتركيب مجاني لكل فلاتر الشرب داخل نطاق الخدمة بأيدي فنيين مدربين.\n## الصيانة وتغيير الشمعات\nزيارات صيانة دورية وتغيير شمعات بقطع غيار أصلية.\n## تحليل المياه\nقياس نسبة الأملاح وترشيح الفلتر المناسب مجاناً.\n## محطات التحلية\nدراسة وتصميم وتركيب محطات تنقية وتحلية للشركات والمصانع."],
        ['payment-methods', 'أنظمة السداد', "## الدفع عند الاستلام\nادفع كاش للمندوب لما الطلب يوصلك.\n## فودافون كاش / إنستاباي\nحوّل قيمة الطلب وابعت صورة التحويل على واتساب.\n## التقسيط\nقسّط مشترياتك على عدة شهور — قدّم طلبك من صفحة التقسيط وهنتواصل معاك."],
        ['how-to-buy', 'كيفية الشراء', "١. اختار المنتج وضيفه للسلة.\n٢. اضغط إتمام الطلب واكتب بيانات التوصيل.\n٣. اختار طريقة الدفع وأكّد الطلب.\n٤. هنتواصل معاك لتأكيد ميعاد التوصيل والتركيب.\nوتقدر كمان تطلب مباشرة على واتساب."],
        ['returns', 'سياسة الإرجاع والاستبدال', "تقدر ترجع أو تستبدل المنتج خلال 14 يوم من الاستلام بشرط يكون بحالته الأصلية وبكامل ملحقاته.\nالشمعات والمنتجات المستعملة أو اللي اتركبت لا يمكن إرجاعها إلا لو فيها عيب صناعة.\nلطلب الإرجاع كلمنا على واتساب أو من صفحة اتصل بنا."],
        ['shipping', 'سياسة الشحن والتركيب', "بنوصل لكل محافظات مصر خلال 1 إلى 4 أيام عمل.\nالشحن مجاني للطلبات فوق الحد المحدد في الموقع.\nالتركيب مجاني لفلاتر الشرب داخل نطاق الخدمة، وبيتم التنسيق معاك على الميعاد المناسب."],
        ['privacy', 'سياسة الخصوصية', "بنستخدم بياناتك (الاسم، رقم الموبايل، العنوان) لتنفيذ طلباتك والتواصل معاك بس.\nمش بنشارك بياناتك مع أي طرف تالت غير شركات الشحن لتوصيل الطلب.\nتقدر تطلب تعديل أو حذف بياناتك في أي وقت."],
        ['terms', 'الشروط والأحكام', "باستخدامك للموقع انت بتوافق على الشروط دي.\nالأسعار قابلة للتغيير، والسعر المعتمد هو السعر وقت تأكيد الطلب.\nالصور للتوضيح وممكن يختلف شكل المنتج بشكل بسيط."],
    ];
    $st = $pdo->prepare('INSERT INTO pages (slug, title, content) VALUES (?,?,?)');
    foreach ($pages as $p) $st->execute($p);

    // ---------- الأسئلة الشائعة العامة ----------
    $faqs = [
        ['هل التركيب مجاني؟', 'أيوه، التركيب مجاني لكل فلاتر الشرب داخل نطاق الخدمة.'],
        ['إمتى لازم أغير الشمعات؟', 'المراحل الأولى كل 3 إلى 6 شهور، والممبرين كل 18 إلى 24 شهر.'],
        ['طرق الدفع المتاحة إيه؟', 'الدفع عند الاستلام، أو فودافون كاش / إنستاباي، أو التقسيط.'],
        ['بتوصلوا لكل المحافظات؟', 'أيوه بنوصل لكل محافظات مصر خلال 1 إلى 4 أيام عمل.'],
    ];
    $st = $pdo->prepare('INSERT INTO faqs (question, answer, sort_order) VALUES (?,?,?)');
    foreach ($faqs as $k => $f) $st->execute([...$f, $k + 1]);

    $pdo->commit();
}
